        // ── Layout helpers ────────────────────────────────────────────────────────

        private enum BtnStyleKind { Primary, Secondary, Success, Danger }

        private static void StyleBtn(System.Windows.Forms.Button btn, string text, BtnStyleKind kind)
        {
            btn.Text      = text;
            btn.FlatStyle = System.Windows.Forms.FlatStyle.Flat;
            btn.Font      = new System.Drawing.Font("Segoe UI", 8.5f);
            btn.Cursor    = System.Windows.Forms.Cursors.Hand;
            btn.UseVisualStyleBackColor = false;
            switch (kind)
            {
                case BtnStyleKind.Primary:
                    btn.BackColor = System.Drawing.Color.FromArgb(46, 116, 181);
                    btn.ForeColor = System.Drawing.Color.White;
                    btn.FlatAppearance.BorderColor = System.Drawing.Color.FromArgb(30, 58, 95);
                    break;
                case BtnStyleKind.Secondary:
                    btn.BackColor = System.Drawing.Color.White;
                    btn.ForeColor = System.Drawing.Color.FromArgb(26, 35, 50);
                    btn.FlatAppearance.BorderColor = System.Drawing.Color.FromArgb(208, 215, 222);
                    break;
                case BtnStyleKind.Success:
                    btn.BackColor = System.Drawing.Color.FromArgb(39, 174, 96);
                    btn.ForeColor = System.Drawing.Color.White;
                    btn.FlatAppearance.BorderColor = System.Drawing.Color.FromArgb(30, 132, 73);
                    break;
                case BtnStyleKind.Danger:
                    btn.BackColor = System.Drawing.Color.White;
                    btn.ForeColor = System.Drawing.Color.FromArgb(231, 76, 60);
                    btn.FlatAppearance.BorderColor = System.Drawing.Color.FromArgb(231, 76, 60);
                    break;
            }
        }

